    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val) public payable {
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint afterSet = c.MinSum(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint afterInit = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(afterSet == val && afterInit == val);
    }
}

