pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        try c.SetMinSum(val) {} catch { return; }
        uint256 afterSet;
        try c.MinSum() returns (uint256 __r) { afterSet = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 afterInit;
        try c.MinSum() returns (uint256 __r) { afterInit = __r; } catch { return; }
        assertTrue(afterSet == val && afterInit == val);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
